CREATE OR REPLACE FUNCTION public.intermediacao_salvar(p_registro jsonb,p_beneficiarios jsonb,p_parcelas jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_id uuid:=(p_registro->>'id')::uuid; v_neg uuid:=NULLIF(p_registro->>'negocio_id','')::uuid; v_lead uuid:=NULLIF(p_registro->>'pipeline_lead_id','')::uuid; v_bruto numeric:=(p_registro->>'valor_bruto')::numeric; v_liquido numeric:=(p_registro->>'valor_liquido')::numeric; v_forma text:=p_registro->>'forma_pagamento'; v_ant public.intermediacoes;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'diretor')) THEN RAISE EXCEPTION 'Acesso restrito à gestão.'; END IF;
 PERFORM public.intermediacao_validar_alocacoes(p_registro,p_beneficiarios);
 p_registro:=jsonb_set(p_registro,'{payload,beneficiarios_validos}',p_beneficiarios,true);
 IF v_lead IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'diretor') OR public.can_access_lead(v_lead)) THEN RAISE EXCEPTION 'Vincule a intermediação a um cliente do seu Pipeline.'; END IF;
 PERFORM 1 FROM public.pipeline_leads WHERE id=v_lead FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Cliente não encontrado.'; END IF;
 IF v_neg IS NOT NULL THEN PERFORM 1 FROM public.negocios WHERE id=v_neg AND pipeline_lead_id=v_lead AND status='ativo' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Negócio não pertence a este cliente.'; END IF; IF EXISTS(SELECT 1 FROM public.negocios WHERE id=v_neg AND fase='ganho' AND intermediacao_id IS NOT NULL) THEN RAISE EXCEPTION 'Preserve o documento de uma venda assinada.'; END IF; END IF;
 IF v_forma IS NULL OR v_forma NOT IN ('pix','zemo','nota_fiscal') OR v_bruto IS NULL OR v_bruto<=0 OR v_bruto::text IN ('NaN','Infinity','-Infinity') OR jsonb_array_length(p_beneficiarios)=0 OR jsonb_array_length(p_parcelas)=0 THEN RAISE EXCEPTION 'Comissão e parcelas inválidas.'; END IF;
 IF (SELECT COALESCE(sum((x->>'valor')::numeric),0) FROM jsonb_array_elements(p_parcelas)x) IS DISTINCT FROM v_bruto THEN RAISE EXCEPTION 'A soma das parcelas deve ser igual à comissão bruta.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_parcelas)x WHERE (x->>'valor')::numeric<=0 OR (x->>'valor')::numeric IS NULL OR (x->>'valor')::numeric IS DISTINCT FROM round((x->>'valor')::numeric,2) OR NULLIF(x->>'vencimento','') IS NULL) THEN RAISE EXCEPTION 'Preencha valor e vencimento das parcelas.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='intermediacoes' AND name=p_registro->>'arquivo_path') THEN RAISE EXCEPTION 'O documento não foi anexado.'; END IF;
 IF EXISTS(SELECT 1 FROM public.intermediacoes WHERE id=v_id AND created_by=auth.uid() AND pipeline_lead_id=v_lead AND negocio_id IS NOT DISTINCT FROM v_neg) THEN RETURN v_id; END IF;
 SELECT * INTO v_ant FROM public.intermediacoes WHERE status='ativa' AND (negocio_id=v_neg OR (v_neg IS NULL AND negocio_id IS NULL AND pipeline_lead_id=v_lead)) FOR UPDATE;
 IF v_ant.id IS NOT NULL THEN IF v_ant.origem='drive_historico' OR EXISTS(SELECT 1 FROM public.negocios_recebimentos WHERE intermediacao_id=v_ant.id AND status='recebido') THEN RAISE EXCEPTION 'Preserve a intermediação histórica ou com recebimentos confirmados.'; END IF; UPDATE public.intermediacoes SET status='substituida' WHERE id=v_ant.id; UPDATE public.negocios_recebimentos SET status='cancelado',updated_at=now() WHERE intermediacao_id=v_ant.id AND status='pendente'; END IF;
 INSERT INTO public.intermediacoes(id,created_by,comprador_nome,tipo_pessoa,empreendimento,unidade,vgv,valor_comissao,corretores,arquivo_path,filename,payload,forma_pagamento,desconto_nf_pct,negocio_id,pipeline_lead_id,valor_bruto,valor_liquido,parcelas) VALUES(v_id,auth.uid(),p_registro->>'comprador_nome',p_registro->>'tipo_pessoa',p_registro->>'empreendimento',p_registro->>'unidade',(p_registro->>'vgv')::numeric,v_bruto,ARRAY(SELECT jsonb_array_elements_text(p_registro->'corretores')),p_registro->>'arquivo_path',p_registro->>'filename',p_registro->'payload',v_forma,CASE WHEN v_forma='nota_fiscal' THEN 10 ELSE 0 END,v_neg,v_lead,v_bruto,v_liquido,p_registro->'parcelas');
 INSERT INTO public.intermediacao_beneficiarios(intermediacao_id,nome,papel,user_id,percentual,valor_bruto,desconto,valor_liquido) SELECT v_id,x->>'nome',x->>'papel',NULLIF(x->>'user_id','')::uuid,(x->>'percentual')::numeric,(x->>'valor_bruto')::numeric,(x->>'desconto')::numeric,(x->>'valor_liquido')::numeric FROM jsonb_array_elements(p_beneficiarios)x;
 INSERT INTO public.negocios_recebimentos(negocio_id,intermediacao_id,parcela_num,vencimento,valor,forma,created_by) SELECT v_neg,v_id,ord::int,(x->>'vencimento')::date,(x->>'valor')::numeric,v_forma,auth.uid() FROM jsonb_array_elements(p_parcelas) WITH ORDINALITY AS t(x,ord);
 IF v_neg IS NOT NULL THEN UPDATE public.negocios SET intermediacao_id=v_id WHERE id=v_neg; END IF; RETURN v_id;
END $$;